/** Convert one Source into the WASM transport shape. */
export function toWasmSource(
    wasm: WasmModule,
    value: Source,
): Wasm.Source {
    if (value.kind === "fileSystem") {
        return wasm.Source.fileSystem(value.path);
    }

    if (value.kind === "memory") {
        return wasm.Source.memory(value.root, value.edits.map((item) => toWasmEdit(wasm, item)));
    }

    throw new Error("unknown Source");
}

